import django
from django.conf import settings

if not settings.configured:
    settings.configure(
        DATABASES={'default': {'ENGINE': 'django.db.backends.sqlite3', 'NAME': ':memory:'}},
        INSTALLED_APPS=['django.contrib.contenttypes', 'django.contrib.auth'],
        DEFAULT_AUTO_FIELD='django.db.models.AutoField',
    )
    django.setup()

from django.db import models
from django.core import checks

# Simulate the models from the issue
class Product(models.Model):
    parent = models.ForeignKey('self', models.CASCADE, null=True)
    class Meta:
        app_label = 'test_app'

class Supply(models.Model):
    product = models.ForeignKey(Product, models.CASCADE)
    class Meta:
        app_label = 'test_app'

class Stock(models.Model):
    supply = models.ForeignKey(Supply, models.CASCADE)
    class Meta:
        app_label = 'test_app'
        ordering = ['supply__product__parent__isnull']

# Run the check
errors = Stock.check()
if errors:
    print("ERRORS found (this is the bug):")
    for e in errors:
        print(f"  {e}")
else:
    print("No errors - fix works!")

# Also test that invalid lookups still raise errors
class Stock2(models.Model):
    supply = models.ForeignKey(Supply, models.CASCADE)
    class Meta:
        app_label = 'test_app'
        ordering = ['supply__product__parent__nonexistent']

errors2 = Stock2.check()
if errors2:
    print("Stock2 correctly reports errors for invalid lookup:")
    for e in errors2:
        print(f"  {e}")
else:
    print("Stock2 ERROR: should have reported errors for invalid lookup!")
EOF
